import { useCallback, useState } from 'react';
import { JxChip, JxTagInput } from '@jinx-ui/react';

export interface ArticleTagPickerProps {
  defaultTags?: string[];
  label?: string;
  placeholder?: string;
  onChange?: (tags: string[]) => void;
}

export default function ArticleTagPicker({
  defaultTags = [],
  label = 'Теги статьи',
  placeholder = 'Введите тег и нажмите Enter',
  onChange,
}: ArticleTagPickerProps) {
  const [tags, setTags] = useState<string[]>(defaultTags);

  const applyTags = useCallback(
    (next: string[]) => {
      setTags(next);
      onChange?.(next);
    },
    [onChange],
  );

  const removeTag = useCallback(
    (tag: string) => {
      applyTags(tags.filter((item) => item !== tag));
    },
    [applyTags, tags],
  );

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
      <span
        style={{
          fontFamily: 'var(--jx-font-sans)',
          fontSize: '13px',
          color: 'var(--jx-text-2)',
        }}
      >
        {label}
      </span>

      <JxTagInput
        ariaLabel={label}
        placeholder={placeholder}
        value={tags}
        onValueChange={applyTags}
      />

      {tags.length > 0 ? (
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
          {tags.map((tag) => (
            <JxChip key={tag} removable onRemove={() => removeTag(tag)}>
              {tag}
            </JxChip>
          ))}
        </div>
      ) : (
        <span
          style={{
            fontFamily: 'var(--jx-font-sans)',
            fontSize: '13px',
            color: 'var(--jx-text-3)',
          }}
        >
          Пока не выбрано ни одного тега
        </span>
      )}
    </div>
  );
}

